int aiburn_parse_device_list(const char* output, AiburnDeviceInfo* devices, int max_devices)
{
    int count = 0;
    const char* p = output;

    if (!output || !devices || max_devices <= 0) return 0;

    /* Find device count */
    const char* count_line = strstr(p, "USB device");
    if (!count_line) {
        /* Try UART devices */
