    }

    /* Parse device entries: "Bus:Port %u: %u-%u" format */
    while (count < max_devices) {
        const char* bus_line = strstr(p, "Bus:Port");
        if (!bus_line) break;

        AiburnDeviceInfo* dev = &devices[count];
        memset(dev, 0, sizeof(*dev));

