void aiburn_log(AiburnContext* ctx, int level, const char* fmt, ...)
{
    char buffer[2048];
    va_list args;

    if (!ctx || !ctx->log_fn || !fmt) return;

    va_start(args, fmt);
    vsnprintf(buffer, sizeof(buffer), fmt, args);
    va_end(args);

    ctx->log_fn(ctx->log_user_data, level, buffer);
}

void aiburn_build_dev_arg(const AiburnDevice* dev, char* buf, unsigned int buf_len)
{
    if (!dev || !buf || buf_len == 0) return;

    if (dev->info.transport == AIB_TRANSPORT_USB) {
        snprintf(buf, buf_len, "-d %u:%u", dev->info.bus, dev->info.port);
    } else {
        /* UART: extract COM port number from path */
        const char* com = strstr(dev->info.path, "COM");
        if (com) {
            snprintf(buf, buf_len, "-u %s", com);
        } else {
            snprintf(buf, buf_len, "-u %s", dev->info.path);
        }
    }
}

const char* aiburn_get_upgcmd_path(AiburnContext* ctx)
{
    if (ctx && ctx->upgcmd_path[0] != '\0') {
        return ctx->upgcmd_path;
    }
    return g_upgcmd_path;
}
