    printf("开始烧录 %s ...\n", argv[1]);
    AiBurnStatus ret = AiBurn_BurnFull(dev, img, progress, NULL);
    printf("\n%s\n", AiBurn_StatusToString(ret));

    /* 5. 清理 */
    AiBurn_ImageFree(img);
    AiBurn_CloseDevice(dev);
    AiBurn_Deinit(ctx);
    return (ret == AIB_OK) ? 0 : 1;
}
